{
  "probability": 0.02,
  "range_low": 0.01,
  "range_high": 0.04,
  "summary": [
    "Base-rate reference class suggests a low base probability for state-actor CW use in Ukraine before May 2026.",
    "Upward signals from OPCW-CS incidents and intelligence claims exist, but attribution remains uncertain.",
    "Stronger deterrents from norms and escalation risks pull the posterior downward, yielding a low but nonzero probability."
  ],
  "confidence": "medium",
  "narrative": "Starting from a low base-rate anchor, we update for battlefield CS and chloropicrin signals (up), but deterrence and escalation risks (down) and attribution uncertainty (neutral) balance toward a small probability. The calibrated posterior is 2% with a wide but plausible uncertainty around it.",
  "justification": {
    "anchor": {
      "probability": 0.04,
      "basis": "Base-rate probability of state-actor chemical weapons use in a modern interstate conflict; anchor chosen to reflect historical low incidence and the Chemical Weapons Convention era context."
    },
    "factor_updates": [
      {
        "factor": "OPCW-confirmed presence of CS on battlefield (CS incidents)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Signals nonzero CW activity, increasing probability modestly."
      },
      {
        "factor": "Intelligence assessments alleging intensified sanctioned CW use (chloropicrin/CS)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Credible intelligence signals raise risk, though attribution remains contested."
      },
      {
        "factor": "International norms and deterrence against CW use",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "CW prohibition and potential sanctions strongly deter use, pulling probability down."
      },
      {
        "factor": "Delivery, targeting, and escalation risks",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Operational challenges and risk of escalation reduce attractiveness of CW use."
      },
      {
        "factor": "Attribution uncertainty",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Ambiguity about perpetrator adds uncertainty without a directional push."
      }
    ],
    "synthesis_rationale": "Starting from a base-rate anchor of 0.04, the up-signals from CS incidents and intelligence are countered by strong downward pressures from norms and practical risks. Given the mixed evidence and attribution uncertainty, the posterior lands at 0.02, with a calibrated range reflecting plausible uncertainty around this low probability."
  }
}

